window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-2b3b55dd3c52918c"]={"versions": [{"id": "FIG-2b3b55dd3c52918c", "releases": ["R18-10-1", "R18-10_R4.4.0_R1.5.0", "R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturelles Bereitstellungs- und Testaufbau-Diagramm (Deployment-/Systemarchitektur) für AUTOSAR Adaptive Platform Systemtests im Bereich Diagnose (Diagnostics). Dargestellt sind zwei Steuergeräte-Zielsysteme (ECU1, ECU2) sowie ein automatisierter Testknoten (Jenkins) und deren Schichtenarchitektur von der Hardware über das Betriebssystem und die Middleware bis zur Anwendungsebene.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Drei primäre Knoten mit Schichtenarchitektur:</p>\n<ul class=\"fig-list\"><li><strong>ECU1</strong>: Hardwareknoten „Intel MinnowBoard“, Betriebssystem „Linux with Real-time Patches“, Bibliotheksschicht „POXIS libs (libc, ...)“, Kommunikationsstack „vSomeIP“ und Funktionscluster „Diagnostic Manager“, Middleware-Schnittstelle „ARA“ (AUTOSAR Runtime for Adaptive Applications) sowie oberste Anwendungsschicht „Video Data“.\n</li><li><strong>ECU2</strong>: Hardwareknoten „Renesas R-CAR H3 ULCB“, Betriebssystem „Linux with Real-time Patches“, Bibliotheksschicht „POXIS libs (libc, ...)“, Middlewarekomponenten „vSomeIP“ und „Diagnostic Manager“, Middleware-Schicht „ARA“ sowie Anwendung „System Test Applications“.\n</li><li><strong>Jenkins</strong>: Hardwareknoten „PC“, Betriebssystem „Linux“, Server-/Automatisierungsumgebung „Jenkins“ sowie darauf ausgeführte Komponente „Diagnostic Tester“.\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und Verbindungspfade: Gestrichelte rote Linien symbolisieren Kommunikations- und Kontrollpfade zwischen dem Testknoten und den Steuergeräten. Ein Pfad koppelt den Jenkins-Knoten über das Netzwerk bzw. den Middleware-/SOME/IP-Stack („vSomeIP“) mit den Anwendungen; ein zweiter Pfad bindet den Jenkins-Knoten über das Netzwerk an den jeweiligen „Diagnostic Manager“ und weiter über ARA an die Anwendungen an. Pfeilspitzen weisen jeweils nach oben in die obersten Anwendungsschichten („Video Data“, „System Test Applications“, „Diagnostic Tester“).</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Systemtopologie zur Testdurchführung. Der Testknoten „Jenkins“ steuert über „Diagnostic Tester“ automatisierte Testfälle ein. Die Interaktion erfolgt über zwei logische Kanäle:</p>\n<ol class=\"fig-list\"><li>Diagnosepfad: Befehle und Abfragen verlaufen vom Diagnosetester über die physikalische Netzwerkanbindung zu den Diagnostic Managern auf ECU1 und ECU2, welche Diagnoseanforderungen verarbeiten und über die ARA-Schnittstellen an die Zielanwendungen weiterleiten bzw. Testergebnisse rückmelden.\n</li><li>Kommunikations-/Servicepfad: Direkter Austausch über den vSomeIP-Stack zwischen den Knoten zur Validierung serviceorientierter Kommunikation.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Informative Architekturskizze aus einem technischen Bericht (TR) zur Veranschaulichung des Referenz-Testaufbaus für Diagnosetests. Sie dient Integratoren und Testentwicklern als Leitfaden für die Hardware-Ausstattung (MinnowBoard, Renesas R-CAR H3), die OS-Konfiguration (Linux mit RT-Patches) sowie die Einbindung der AUTOSAR Adaptive Core-Dienste (Diagnostic Manager, vSomeIP/SOME/IP-Stack) in eine automatisierte Continuous-Integration-Testumgebung (Jenkins).</p>"}, {"id": "FIG-6e53cc4bfbe655e7", "releases": ["R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturelles Bereitstellungs- und Testaufbau-Diagramm (Deployment-/Systemarchitektur) für AUTOSAR Adaptive Platform Systemtests im Bereich Diagnose (Diagnostics). Dargestellt sind zwei Steuergeräte-Zielsysteme (ECU1, ECU2) sowie ein automatisierter Testknoten (Jenkins) und deren Schichtenarchitektur von der Hardware über das Betriebssystem und die Middleware bis zur Anwendungsebene.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Drei primäre Knoten mit Schichtenarchitektur:</p>\n<ul class=\"fig-list\"><li><strong>ECU1</strong>: Hardwareknoten „Intel MinnowBoard“, Betriebssystem „Linux with Real-time Patches“, Bibliotheksschicht „POSIX libs (libc, ...)“, Kommunikationsstack „vSomeIP“ und Funktionscluster „Diagnostic Manager“, Middleware-Schnittstelle „ARA“ (AUTOSAR Runtime for Adaptive Applications) sowie oberste Anwendungsschicht „DIAG Test Application(s)“.\n</li><li><strong>ECU2</strong>: Hardwareknoten „Renesas R-CAR H3 ULCB“, Betriebssystem „Linux with Real-time Patches“, Bibliotheksschicht „POSIX libs (libc, ...)“, Middlewarekomponenten „vSomeIP“ und „Diagnostic Manager“, Middleware-Schicht „ARA“ sowie Anwendungsschicht „DIAG Test Application(s)“.\n</li><li><strong>Jenkins</strong>: Hardwareknoten „PC“, Betriebssystem „Linux“, Server-/Automatisierungsumgebung „Jenkins“ sowie darauf ausgeführte Komponente „DIAG Tester“.\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und Verbindungspfade: Gestrichelte rote Linien symbolisieren Kommunikations- und Kontrollpfade zwischen dem Testknoten und den Steuergeräten. Ein Pfad koppelt den Jenkins-Knoten über das Netzwerk bzw. den Middleware-/SOME/IP-Stack („vSomeIP“) mit den Anwendungen; ein zweiter Pfad bindet den Jenkins-Knoten über das Netzwerk an den jeweiligen „Diagnostic Manager“ und weiter über ARA an die Anwendungen an. Pfeilspitzen weisen jeweils nach oben in die obersten Anwendungsschichten („DIAG Test Application(s)“, „DIAG Tester“).</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Systemtopologie zur Testdurchführung. Der Testknoten „Jenkins“ steuert über „Diagnostic Tester“ automatisierte Testfälle ein. Die Interaktion erfolgt über zwei logische Kanäle:</p>\n<ol class=\"fig-list\"><li>Diagnosepfad: Befehle und Abfragen verlaufen vom Diagnosetester über die physikalische Netzwerkanbindung zu den Diagnostic Managern auf ECU1 und ECU2, welche Diagnoseanforderungen verarbeiten und über die ARA-Schnittstellen an die Zielanwendungen weiterleiten bzw. Testergebnisse rückmelden.\n</li><li>Kommunikations-/Servicepfad: Direkter Austausch über den vSomeIP-Stack zwischen den Knoten zur Validierung serviceorientierter Kommunikation.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Informative Architekturskizze aus einem technischen Bericht (TR) zur Veranschaulichung des Referenz-Testaufbaus für Diagnosetests. Sie dient Integratoren und Testentwicklern als Leitfaden für die Hardware-Ausstattung (MinnowBoard, Renesas R-CAR H3), die OS-Konfiguration (Linux mit RT-Patches) sowie die Einbindung der AUTOSAR Adaptive Core-Dienste (Diagnostic Manager, vSomeIP/SOME/IP-Stack) in eine automatisierte Continuous-Integration-Testumgebung (Jenkins).</p>"}, {"id": "FIG-3132e66f31255ea8", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Blockdiagramm / Test- und Deployment-Architekturdiagramm für System- und Integrationstests der AUTOSAR Adaptive Platform (AP). Das Diagramm veranschaulicht den Testaufbau (Test Setup) für den Funktionsbereich Diagnostics (UDS/DoIP) über ein heterogenes Multi-ECU-Netzwerk hinweg, gesteuert und automatisiert durch einen externen CI/CD-Host (Jenkins).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Setup umfasst drei Hauptknoten, die über zwei separate logische/physikalische Netzwerkverbindungen (gestrichelte rote Linien) gekoppelt sind:</p>\n<ul class=\"fig-list\"><li><strong>ECU1 (Target Node 1):</strong>\n<ul class=\"fig-list\"><li>Hardware: Intel MinnowBoard.\n</li><li>Betriebssystem: Linux with Real-time Patches.\n</li><li>Laufzeitumgebung: POSIX libs (libc, ...).\n</li><li>Plattform-Dienste / Middleware: <code>vSomeIP</code> und <code>Diagnostic Manager</code> (DM).\n</li><li>Schnittstellenschicht: <code>ARA</code> (AUTOSAR Runtime for Adaptive Applications).\n</li><li>Applikationsebene: <code>DIAG Test Application(s)</code>.\n</li></ul>\n</li><li><strong>ECU2 (Target Node 2):</strong>\n<ul class=\"fig-list\"><li>Hardware: Renesas R-CAR H3 ULCB.\n</li><li>Betriebssystem: Linux with Real-time Patches.\n</li><li>Laufzeitumgebung: POSIX libs (libc, ...).\n</li><li>Plattform-Dienste / Middleware: <code>vSomeIP</code> und <code>Diagnostic Manager</code>.\n</li><li>Schnittstellenschicht: <code>ARA</code>.\n</li><li>Applikationsebene: <code>DIAG Test Application(s)</code>.\n</li></ul>\n</li><li><strong>Jenkins (Test Master / Automation Node):</strong>\n<ul class=\"fig-list\"><li>Hardware: PC.\n</li><li>Betriebssystem: Linux.\n</li><li>Middleware/Automationsschicht: Jenkins CI/CD Engine.\n</li><li>Test-Entität: <code>DIAG Tester</code>.\n</li></ul>\n</li><li><strong>Schnittstellen &amp; Verbindungsnetz:</strong>\n<ul class=\"fig-list\"><li>Zwei Ethernet-basierte Netzwerkpfade koppeln die Knoten: Ein Pfad verbindet die <code>vSomeIP</code>-Instanzen über die POSIX-Netzwerk-Stacks von ECU1 und ECU2. Ein zweiter Netzwerkpfad verbindet den <code>DIAG Tester</code> auf dem Jenkins-PC mit den <code>Diagnostic Manager</code>-Instanzen auf ECU1 und ECU2 (Diagnose-Kommunikation, z. B. DoIP).\n</li><li>Innerhalb der ECUs greifen <code>DIAG Test Application(s)</code> über die <code>ARA</code>-Schnittstellen (ara::diag / ara::com) auf den <code>Diagnostic Manager</code> bzw. <code>vSomeIP</code> zu.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Test-Initialisierung &amp; Trigger:</strong> Der CI/CD-Server (Jenkins) stößt über die Komponente <code>DIAG Tester</code> Diagnosetests an.\n</li><li><strong>Diagnose-Kommunikation (DoIP/UDS):</strong> Die Diagnoseanfragen (Diagnostic Requests) werden vom <code>DIAG Tester</code> über das Diagnosenetzwerk an die <code>Diagnostic Manager</code>-Instanzen auf ECU1 (Intel MinnowBoard) und ECU2 (Renesas R-CAR H3 ULCB) übertragen.\n</li><li><strong>Plattform- und Applikationsverarbeitung:</strong>\n<ul class=\"fig-list\"><li>Der <code>Diagnostic Manager</code> verarbeitet die UDS-Dienste und leitet relevante Diagnoseroutinen, Data Identifier (DIDs) oder Event-Meldungen über die standardisierten <code>ARA</code>-Schnittstellen an die lokalen <code>DIAG Test Application(s)</code> weiter.\n</li><li>Parallele oder serviceorientierte Kommunikation zwischen den Steuergeräten ECU1 und ECU2 erfolgt über den <code>vSomeIP</code>-Kanal.\n</li></ul>\n</li><li><strong>Rückmeldung &amp; Verifikation:</strong> Die Test-Applikationen bzw. der <code>Diagnostic Manager</code> senden Diagnostic Responses zurück an den <code>DIAG Tester</code> auf dem Jenkins-Host, welcher die Testergebnisse auswertet und protokolliert.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Schaubild besitzt informativen Charakter (Technical Report, TR) zur Verifikation von AUTOSAR Adaptive Platform Implementierungen. Es definiert eine Referenz-Testarchitektur zur automatisierten Validierung der <code>ara::diag</code>-Funktionalität in heterogenen Hardware-Umgebungen (x86_64 via Intel MinnowBoard und ARM64 via Renesas R-CAR H3). Entwickler und Integratoren müssen sicherstellen, dass die POSIX-Netzwerktreiber DoIP-Verkehr für den Diagnostic Manager und SOME/IP-Verkehr für vSomeIP parallel und echtzeitfähig verarbeiten können.</p>"}], "trans": [{"from": "FIG-2b3b55dd3c52918c", "to": "FIG-6e53cc4bfbe655e7", "fr": "R19-03", "tr": "R19-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Umbenennung der Testanwendungen in den obersten Boxen:\n<ul class=\"fig-list\"><li>ECU1: „Video Data“ zu „DIAG Test Application(s)“\n</li><li>ECU2: „System Test Applications“ zu „DIAG Test Application(s)“\n</li><li>Jenkins: „Diagnostic Tester“ zu „DIAG Tester“\n</li></ul>\n</li><li>Korrektur eines Tippfehlers in den Betriebssystem-Bibliotheken von ECU1 und ECU2: „POXIS libs (libc, ...)“ zu „POSIX libs (libc, ...)“\n</li><li>Bereinigung der unteren gestrichelten Verbindungslinien: Überstehende vertikale Linienstummel unterhalb der Verbindungslinien an den Schnittpunkten wurden entfernt.\n</li></ul>"}]};
